package dev.groundzero.world;

import com.mojang.serialization.MapCodec;

import dev.groundzero.GroundZero;
import net.minecraft.core.registries.Registries;
import net.minecraft.world.level.levelgen.placement.PlacementModifier;
import net.neoforged.neoforge.registries.DeferredHolder;
import net.neoforged.neoforge.registries.DeferredRegister;

/** Worldgen code registrations. The features themselves are data (generated by {@code GZWorldgenData}). */
public final class GZWorldgen {
    public static final DeferredRegister<MapCodec<? extends PlacementModifier>> PLACEMENT_MODIFIERS =
            DeferredRegister.create(Registries.PLACEMENT_MODIFIER_TYPE, GroundZero.MODID);

    public static final DeferredHolder<MapCodec<? extends PlacementModifier>, MapCodec<ConfigToggleFilter>> CONFIG_TOGGLE =
            PLACEMENT_MODIFIERS.register("config_toggle", () -> ConfigToggleFilter.CODEC);

    private GZWorldgen() {}
}
